#[derive(Debug, Clone)]
pub enum Pattern {
    Literal(char),
    Dot,
    CharClass(Vec<(char, char)>),
    Digit,
    Word,
    Space,
    AnchorStart,
    AnchorEnd,
    Star(Box<Pattern>),
    Plus(Box<Pattern>),
    Question(Box<Pattern>),
    Sequence(Vec<Pattern>),
    Alternation(Vec<Pattern>),
}

pub struct Regex { pattern: Pattern }

impl Regex {
    pub fn new(pattern: &str) -> Result<Self, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let (pat, _) = parse_sequence(&chars, 0)?;
        Ok(Regex { pattern: pat })
    }

    pub fn is_match(&self, input: &str) -> bool {
        let chars: Vec<char> = input.chars().collect();
        match_match(&self.pattern, &chars, 0).is_some()
    }
}

fn parse_sequence(chars: &[char], mut pos: usize) -> Result<(Pattern, usize), String> {
    let mut patterns = Vec::new();
    while pos < chars.len() {
        match chars[pos] {
            '|' => {
                pos += 1;
                let (right, new_pos) = parse_sequence(chars, pos)?;
                patterns.push(right);
                return Ok((Pattern::Alternation(patterns), new_pos));
            }
            ')' => return Ok((Pattern::Sequence(patterns), pos)),
            '^' => { patterns.push(Pattern::AnchorStart); pos += 1; }
            '$' => { patterns.push(Pattern::AnchorEnd); pos += 1; }
            '.' => { patterns.push(Pattern::Dot); pos += 1; }
            '*' => { let last = patterns.pop().ok_or("Nothing to repeat")?; patterns.push(Pattern::Star(Box::new(last))); pos += 1; }
            '+' => { let last = patterns.pop().ok_or("Nothing to repeat")?; patterns.push(Pattern::Plus(Box::new(last))); pos += 1; }
            '?' => { let last = patterns.pop().ok_or("Nothing to repeat")?; patterns.push(Pattern::Question(Box::new(last))); pos += 1; }
            'd' => { patterns.push(Pattern::Digit); pos += 1; }
            'w' => { patterns.push(Pattern::Word); pos += 1; }
            's' => { patterns.push(Pattern::Space); pos += 1; }
            _ => { patterns.push(Pattern::Literal(chars[pos])); pos += 1; }
        }
    }
    Ok((Pattern::Sequence(patterns), pos))
}

fn match_match(pattern: &Pattern, input: &[char], pos: usize) -> Option<usize> {
    match pattern {
        Pattern::Literal(c) => {
            if pos < input.len() && input[pos] == *c { Some(pos + 1) } else { None }
        }
        Pattern::Dot => {
            if pos < input.len() { Some(pos + 1) } else { None }
        }
        Pattern::Digit => {
            if pos < input.len() && input[pos].is_ascii_digit() { Some(pos + 1) } else { None }
        }
        Pattern::Word => {
            if pos < input.len() && (input[pos].is_alphanumeric() || input[pos] == '_') { Some(pos + 1) } else { None }
        }
        Pattern::Space => {
            if pos < input.len() && input[pos].is_whitespace() { Some(pos + 1) } else { None }
        }
        Pattern::AnchorStart => {
            if pos == 0 { Some(0) } else { None }
        }
        Pattern::AnchorEnd => {
            if pos == input.len() { Some(pos) } else { None }
        }
        Pattern::Sequence(pats) => {
            let mut current = pos;
            for p in pats {
                current = match_match(p, input, current)?;
            }
            Some(current)
        }
        Pattern::Alternation(pats) => {
            for p in pats {
                if let Some(new_pos) = match_match(p, input, pos) {
                    return Some(new_pos);
                }
            }
            None
        }
        _ => None,
    }
}

