#[derive(Debug, Clone)]
pub struct CharRange { pub from: char, pub to: char }
impl CharRange {
    fn single(c: char) -> Self { CharRange { from: c, to: c } }
    fn contains(&self, c: char) -> bool { c >= self.from && c <= self.to }
