#[derive(Debug, Clone)]
pub enum Pattern {
    Literal(char), Dot, CharClass(Vec<CharRange>), NegCharClass(Vec<CharRange>),
    Digit, Word, Space, AnchorStart, AnchorEnd,
    Star(Box<Pattern>), Plus(Box<Pattern>), Question(Box<Pattern>),
    Repeat { pattern: Box<Pattern>, min: usize, max: Option<usize>, greedy: bool },
    Group(Box<Pattern>), Sequence(Vec<Pattern>), Alternation(Vec<Pattern>),
}
#[derive(Debug, Clone)] pub struct CharRange { pub from: char, pub to: char }
impl CharRange { fn single(c: char) -> Self { CharRange { from: c, to: c } } fn contains(&self, c: char) -> bool { c >= self.from && c <= self.to } }
pub struct Regex { pattern: Pattern, anchored_start: bool, anchored_end: bool }
impl Regex {
    pub fn new(pattern: &str) -> Result<Self, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let anchored_start = chars.first() == Some(&'^');
        let anchored_end = chars.last() == Some(&'$');
        let start = if anchored_start { 1 } else { 0 };
        let end = if anchored_end { chars.len() - 1 } else { chars.len() };
        let (pat, _) = parse_sequence(&chars[start..end], 0)?;
        Ok(Regex { pattern: pat, anchored_start, anchored_end })
    }
    pub fn is_match(&self, input: &str) -> bool {
        let chars: Vec<char> = input.chars().collect();
        if self.anchored_start {
            match_pattern(&self.pattern, &chars, 0).map_or(false, |pos| !self.anchored_end || pos == chars.len())
        } else {
            (0..=chars.len()).any(|s| match_pattern(&self.pattern, &chars, s).map_or(false, |pos| !self.anchored_end || pos == chars.len()))
        }
    }
    pub fn find(&self, input: &str) -> Option<&str> {
        let chars: Vec<char> = input.chars().collect();
        for start in 0..=chars.len() {
            if let Some(end) = match_pattern(&self.pattern, &chars, start) {
                let start_byte = chars[..start].iter().collect::<String>().len();
                let end_byte = chars[..end].iter().collect::<String>().len();
                return Some(&input[start_byte..end_byte]);
            }
        }
        None
    }
    pub fn find_all(&self, input: &str) -> Vec<&str> {
        let mut results = Vec::new();
        let mut chars: Vec<char> = input.chars().collect();
        let mut start = 0;
        while start <= chars.len() {
            if let Some(end) = match_pattern(&self.pattern, &chars, start) {
                let start_byte = chars[..start].iter().collect::<String>().len();
                let end_byte = chars[..end].iter().collect::<String>().len();
                results.push(&input[start_byte..end_byte]);
                start = if end == start { start + 1 } else { end };
            } else { start += 1; }
        }
        results
    }
}

fn parse_sequence(chars: &[char], mut pos: usize) -> Result<(Pattern, usize), String> {
    let mut patterns = Vec::new();
    while pos < chars.len() && chars[pos] != ')' {
        match chars[pos] {
            '|' => { pos += 1; let (r, np) = parse_sequence(chars, pos)?; patterns.push(r); return Ok((Pattern::Alternation(patterns), np)); }
            '^' => { patterns.push(Pattern::AnchorStart); pos += 1; }
            '$' => { patterns.push(Pattern::AnchorEnd); pos += 1; }
            '.' => { patterns.push(Pattern::Dot); pos += 1; }
            '(' => { pos += 1; let (inner, np) = parse_sequence(chars, pos)?; pos = np + 1; patterns.push(Pattern::Group(Box::new(inner))); }
            '[' => {
                pos += 1; let neg = if pos < chars.len() && chars[pos] == '^' { pos += 1; true } else { false };
                let mut ranges = Vec::new();
                while pos < chars.len() && chars[pos] != ']' {
                    if pos + 2 < chars.len() && chars[pos + 1] == '-' && chars[pos + 2] != ']' { ranges.push(CharRange { from: chars[pos], to: chars[pos + 2] }); pos += 3; }
                    else { ranges.push(CharRange::single(chars[pos])); pos += 1; }
                }
                if pos < chars.len() { pos += 1; }
                if neg { patterns.push(Pattern::NegCharClass(ranges)); } else { patterns.push(Pattern::CharClass(ranges)); }
            }
            '\' => { pos += 1; if pos >= chars.len() { return Err("Trailing backslash".to_string()); } match chars[pos] { 'd' => patterns.push(Pattern::Digit), 'w' => patterns.push(Pattern::Word), 's' => patterns.push(Pattern::Space), c => patterns.push(Pattern::Literal(c)) } pos += 1; }
            _ => { patterns.push(Pattern::Literal(chars[pos])); pos += 1; }
        }
    }
    Ok((Pattern::Sequence(patterns), pos))
}

fn match_pattern(pattern: &Pattern, input: &[char], pos: usize) -> Option<usize> {
    match pattern {
        Pattern::Literal(c) => if pos < input.len() && input[pos] == *c { Some(pos + 1) } else { None },
        Pattern::Dot => if pos < input.len() { Some(pos + 1) } else { None },
        Pattern::Digit => if pos < input.len() && input[pos].is_ascii_digit() { Some(pos + 1) } else { None },
        Pattern::Word => if pos < input.len() && (input[pos].is_alphanumeric() || input[pos] == '_') { Some(pos + 1) } else { None },
        Pattern::Space => if pos < input.len() && input[pos].is_whitespace() { Some(pos + 1) } else { None },
        Pattern::CharClass(ranges) => if pos < input.len() && ranges.iter().any(|r| r.contains(input[pos])) { Some(pos + 1) } else { None },
        Pattern::NegCharClass(ranges) => if pos < input.len() && !ranges.iter().any(|r| r.contains(input[pos])) { Some(pos + 1) } else { None },
        Pattern::AnchorStart => if pos == 0 { Some(0) } else { None },
        Pattern::AnchorEnd => if pos == input.len() { Some(pos) } else { None },
        Pattern::Sequence(pats) => { let mut cur = pos; for p in pats { cur = match_pattern(p, input, cur)?; } Some(cur) }
        Pattern::Alternation(pats) => { for p in pats { if let Some(np) = match_pattern(p, input, pos) { return Some(np); } } None }
        Pattern::Group(p) => match_pattern(p, input, pos),
        Pattern::Star(p) => { let mut cur = pos; while let Some(np) = match_pattern(p, input, cur) { cur = np; } Some(cur) }
        Pattern::Plus(p) => { let np = match_pattern(p, input, pos)?; let mut cur = np; while let Some(np) = match_pattern(p, input, cur) { cur = np; } Some(cur) }
        Pattern::Question(p) => match_pattern(p, input, pos).or(Some(pos)),
        Pattern::Repeat { pattern: p, min, max, .. } => {
            let mut matches = vec![pos]; let mut cur = pos; let actual_max = max.unwrap_or(usize::MAX);
            while matches.len() < actual_max { match match_pattern(p, input, cur) { Some(np) => { cur = np; matches.push(cur); } None => break } }
            if matches.len() < min { None } else { Some(matches[min]) }
        }
    }
}
